    drop(bits);
    drop(before);
    drop(old);
    drop(recycled);

    // No packed/sparse scratch: prefill_packed takes the serial fallback.
    let mut serial = fresh(&ctx, &weights, 16, 0);
    serial.prefill(&ctx, &tokens[..7]).unwrap();
    let mut oracle = fresh(&ctx, &weights, 16, 0);
