        first_piece_ms: Option<f64>,
    }
    impl GenerationSink for TimedSink {
        fn piece(&mut self, _: &[u8]) -> io::Result<()> {
            self.first_piece_ms
                .get_or_insert_with(|| self.started.elapsed().as_secs_f64() * 1e3);
            Ok(())
        }
        fn tick(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

